final class Config {
    private Config() {}

    static final String DEFAULT_GRAVITY = "left";
    static final String REDO_MODE = "visited";
    static final boolean SUB_GROUP = false;
    static final boolean HAS_CLASSES = false;
    static final boolean HAS_DIGIT = true;
    static final boolean HAS_ANCHORS = false;
