    g, w = got.split("\n"), want.split("\n")
    for i in range(max(len(g), len(w))):
        a = g[i] if i < len(g) else "<missing>"
        b = w[i] if i < len(w) else "<missing>"
        if a != b:
            return "line %d:\n      got:  %s\n      want: %s" % (i + 1, a[:200], b[:200])
    return "(no difference found)"


