    why = []
    if c.get("static"):
        if res["hits"]:
            why.append("%s still contains %s" % (c["static"]["path"], ", ".join(repr(h) for h in res["hits"])))
        if res.get("missing"):
            why.append("%s does not use the new API" % c["static"]["path"])
        return why
